<script setup>
import {usePlay} from './usePlay.js';
import ActivityFields from './ActivityFields.vue';
import H5PPlayer from './H5PPlayer.vue';
import ReviewPanel from './ReviewPanel.vue';
const m=usePlay();
const {capabilities,submission,integrated,commonsBase,submitReview,loadPublication,base,TYPES,TYPE_LABELS,language,t,view,ready,busy,form,saved,formError,message,messageError,savingDisabled,demoUrl,catalog,catalogDraft,catalogMessage,library,bank,bankDialog,adminInput,adminToken,published,editorTitle,choose,go,changeLanguage,saveActivity,openLibrary,filterLibrary,applyToken,removeActivity,publication,saveCatalog,openBank,loadBank,addFromBank,closeBank,copy,onStatement}=m;
const icons=['✓','¿?','▦','↔','⇄','☷','＿','⌕','↔','✓','▣','▦','➜'];
function catalogLabel(value){const lang=language.value==='va'?'ca':language.value;return catalog.value.labels?.[value]?.[lang]||value;}
</script>
<template>
 <header class="topbar"><a class="brand" :href="base+'/'">EduTicTac Play</a><div class="topbar-actions"><edutictac-account v-if="commonsBase!==null" id="accountWidget" :data-base="commonsBase" :data-home="integrated?(commonsBase||'')+'/':null" :data-lang="language" data-no-reload></edutictac-account><label class="language"><span>{{t('language')}}</span><select id="language" :value="language" :disabled="busy" @change="changeLanguage($event.target.value)"><option value="es">ES</option><option value="ca">CA</option><option value="va">VA</option><option value="en">EN</option></select></label></div></header>
 <main class="shell"><p v-if="integrated&&!capabilities.can_publish&&!capabilities.can_submit" class="actions"><a class="button secondary" :href="base+'/api/publication/login'">{{t('teacherLogin')}}</a><span>{{t('loginToSave')}}</span></p>
 <p v-if="!ready" role="status">{{t('libraryLoading')}}</p>
 <section v-show="view==='home'&&ready" id="home" class="panel hero"><p class="eyebrow">EduTicTac Commons</p><h1>{{t('homeTitle')}}</h1><p>{{t('homeIntro')}}</p><p v-if="demoUrl" class="test-phase" role="note"><strong>{{t('testPhaseTitle')}}</strong> {{t('testPhaseNotice')}}</p><p v-if="demoUrl" id="demoNotice" class="test-phase demo-notice" role="note"><strong>{{t('demoTitle')}}</strong> {{t('demoNotice')}} <a id="demoLink" :href="demoUrl">{{t('demoLink')}}</a></p><p v-else class="muted">{{t(integrated?'productionNotice':'anonymousNotice')}}</p><div class="actions"><button v-if="capabilities.can_review" id="openReviews" class="button" @click="go('reviews')">{{t('reviewsTitle')}}</button><a v-if="integrated&&!capabilities.can_publish&&!capabilities.can_submit" id="playLogin" class="button secondary" :href="base+'/api/publication/login'">{{t('teacherLogin')}}</a></div><div class="type-grid"><button v-for="(type,index) in TYPES" :key="type" class="type-card" :data-type="type" :disabled="busy" @click="choose(type)"><span class="type-icon">{{icons[index]}}</span><strong>{{t(TYPE_LABELS[type])}}</strong><small>{{t(type==='compound'?'compound.help':TYPE_LABELS[type]+'Help')}}</small></button></div><div class="actions"><button id="openLibrary" type="button" class="button secondary" @click="openLibrary">{{t('libraryOpen')}}</button></div></section>
 <section v-show="view==='editor'&&ready" id="editor" class="panel" aria-labelledby="editorTitle"><div class="section-heading"><div><p class="eyebrow">EduTicTac Play</p><h1 id="editorTitle">{{editorTitle}}</h1></div><button id="backHome" class="button secondary" :disabled="busy" @click="go('home')">{{t('back')}}</button></div><form id="activityForm" novalidate @submit.prevent="saveActivity(true)"><fieldset class="editor-controls" :disabled="busy"><label><span>{{t('title')}}</span><input id="title" v-model="form.title" maxlength="200" required :placeholder="t('titlePlaceholder')"></label><label><span>{{t('question')}}</span><textarea id="question" v-model="form.question" maxlength="2000" required :placeholder="t('questionPlaceholder')"></textarea></label><ActivityFields :key="form" :form="form" :t="t" :busy="busy" @bank="openBank" @image-error="formError=t('imageError')" @image-busy="m.imageTasks.value+=$event" />
 <fieldset id="catalogField"><legend>{{t('catalog.legend')}}</legend><label v-for="field in [{id:'subject',key:'subject',list:'subjects',label:'subject'},{id:'educationalStage',key:'educational_stage',list:'educational_stages',label:'stage'},{id:'educationalLevel',key:'educational_level',list:'levels',label:'level'}]" :key="field.id"><span>{{t('catalog.'+field.label)}}</span><select :id="field.id" v-model="form[field.key]"><option value=""></option><option v-if="form[field.key]&&!(catalog[field.list]||[]).includes(form[field.key])" :value="form[field.key]">{{catalogLabel(form[field.key])}}</option><option v-for="value in catalog[field.list]||[]" :key="value" :value="value">{{catalogLabel(value)}}</option></select></label><label><span>{{t('catalog.tags')}}</span><select id="activityTags" v-model="form.tags" multiple size="4"><option v-for="value in [...new Set([...(catalog.tags||[]),...(form.tags||[])])]" :key="value" :value="value">{{catalogLabel(value)}}</option></select></label></fieldset>
 </fieldset><p id="formError" class="error" role="alert">{{formError}}</p><div class="actions"><button id="preview" type="submit" class="button" :disabled="savingDisabled">{{t('preview')}}</button><button id="save" type="button" class="button secondary" :disabled="savingDisabled" @click="saveActivity(false)">{{t('save')}}</button></div></form></section>
 <section v-if="view==='previewPanel'&&saved" id="previewPanel" class="panel" aria-labelledby="previewTitle"><div class="section-heading"><div><p class="eyebrow">{{t('previewEyebrow')}}</p><h1 id="previewTitle">{{saved.title}}</h1></div><button id="edit" class="button secondary" :disabled="busy" @click="go('editor')">{{t('edit')}}</button></div><H5PPlayer :base="base" :activity="saved" :on-statement="onStatement">{{t('playerError')}}</H5PPlayer>
 <div v-if="saved.id.startsWith('preview-')" id="previewActions" class="actions"><button id="savePreview" class="button" :disabled="savingDisabled" @click="saveActivity(false)">{{t('save')}}</button><span>{{t('previewOnly')}}</span></div>
 <div v-else id="savedActions" class="actions"><a id="download" class="button" :href="base+'/api/activities/'+saved.id+'/download'">{{t('download')}}</a><button v-if="!published&&capabilities.can_publish" id="publishRecursos" class="button" :disabled="busy" @click="publication(false)">{{t('publishRecursos')}}</button><button v-else-if="published&&capabilities.can_publish" id="unpublishRecursos" class="button secondary" :disabled="busy" @click="publication(true)">{{t('unpublishRecursos')}}</button><button v-if="capabilities.can_submit" id="submitPlayReview" class="button" :disabled="busy||['pending','approved'].includes(submission?.status)" @click="submitReview">{{t('reviewSubmit')}}</button><button id="copy" class="button secondary" @click="copy">{{t('copy')}}</button><button v-if="saved.owned" id="deleteSaved" class="button secondary" :disabled="busy" @click="removeActivity(saved.id)">{{t('deleteActivity')}}</button></div><p v-if="submission" id="submissionStatus" role="status">{{t('reviewStatus.'+submission.status)}}<span v-if="submission.feedback"> · {{submission.feedback}}</span></p><p id="savedMessage" :class="{error:messageError}" role="status">{{message?t(message):''}}</p><p v-if="formError" class="error" role="alert">{{formError}}</p></section>
 <section v-show="view==='library'&&ready" id="library" class="panel" aria-labelledby="libraryTitle"><div class="section-heading"><div><p class="eyebrow">EduTicTac Play</p><h1 id="libraryTitle">{{t('libraryTitle')}}</h1></div><button id="libraryBack" class="button secondary" :disabled="busy" @click="go('home')">{{t('back')}}</button></div><form class="library-filters" @submit.prevent="filterLibrary()"><input id="librarySearch" v-model="library.term" type="search" :placeholder="t('librarySearchPlaceholder')" :aria-label="t('libraryFilter')"><select id="libraryType" v-model="library.type" :aria-label="t('compound.type')" @change="filterLibrary()"><option value="">{{t('libraryAllTypes')}}</option><option v-for="type in TYPES" :key="type" :value="type">{{t(TYPE_LABELS[type])}}</option></select><button id="libraryFilter" type="submit" class="button secondary" :disabled="busy">{{t('libraryFilter')}}</button></form><p id="libraryStatus" class="library-status" role="status">{{library.loading?t('libraryLoading'):library.error?t('libraryError'):t('libraryStatus').replace(':from',library.total?library.offset+1:0).replace(':to',library.offset+library.items.length).replace(':total',library.total)}}</p><div id="libraryList" class="library-grid"><p v-if="!library.loading&&!library.error&&!library.items.length" class="library-status">{{t('libraryEmpty')}}</p><article v-for="activity in library.items" :key="activity.id" class="library-card"><h2>{{activity.title}}</h2><p class="library-meta">{{t(TYPE_LABELS[activity.type]||activity.type)}} · {{(activity.createdAt||'').slice(0,10)}}{{activity.owned?' · '+t('libraryYours'):''}}</p><div class="library-card-actions"><a class="button" :href="base+'/'+activity.id">{{t('libraryOpenActivity')}}</a><a class="button secondary" :href="base+'/api/activities/'+activity.id+'/download'">{{t('download')}}</a><button v-if="activity.owned||adminToken" type="button" class="button secondary" :disabled="busy" @click="removeActivity(activity.id,true)">{{t('libraryDelete')}}</button></div></article></div><div class="actions"><button id="libraryPrev" type="button" class="button secondary" :disabled="library.loading||busy||library.offset<=0" @click="filterLibrary(Math.max(0,library.offset-12))">{{t('libraryPrev')}}</button><button id="libraryNext" type="button" class="button secondary" :disabled="library.loading||busy||!library.hasMore" @click="filterLibrary(library.offset+12)">{{t('libraryNext')}}</button></div>
 <details class="library-admin"><summary>{{t('libraryAdmin')}}</summary><label><span>{{t('libraryAdminToken')}}</span><input id="libraryToken" v-model="adminInput" type="password" autocomplete="off"></label><button id="libraryTokenSave" type="button" class="button secondary" :disabled="busy" @click="applyToken">{{t('libraryTokenSave')}}</button><p class="muted">{{t('libraryAdminHelp')}}</p><div id="catalogAdminEditor"><fieldset><legend>{{t('catalogAdmin')}}</legend><p class="muted">{{t('catalogAdminHelp')}}</p><label v-for="(key,index) in ['subjects','educational_stages','levels','tags']" :key="key"><span>{{t('catalog.'+['subject','stage','level','tags'][index])}}</span><textarea :id="['catalogSubjects','catalogStages','catalogLevels','catalogTags'][index]" v-model="catalogDraft[key]" rows="3"></textarea></label><button id="catalogSave" type="button" class="button secondary" :disabled="busy" @click="saveCatalog">{{t('catalogSave')}}</button><p id="catalogStatus" class="muted" role="status">{{catalogMessage?t(catalogMessage):''}}</p></fieldset></div></details></section>
 <template v-if="view==='reviews'&&capabilities.can_review"><button id="reviewsBack" class="button secondary" @click="go('home')">{{t('back')}}</button><ReviewPanel :base="base" :t="t" /></template>
 <dialog ref="bankDialog" id="compoundBankDialog" @cancel="closeBank"><form method="dialog" class="bank-dialog" @submit.prevent="closeBank"><div class="section-heading"><h2>{{t('bank.title')}}</h2><button type="submit" class="button secondary">{{t('bank.close')}}</button></div><label><span>{{t('bank.search')}}</span><input id="compoundBankSearch" v-model="bank.term" type="search" @input="loadBank"></label><div id="compoundBankList" class="bank-list"><p v-if="bank.loading" class="library-status">{{t('bank.loading')}}</p><p v-else-if="bank.error" role="alert">{{t('libraryError')}}</p><p v-else-if="!bank.items.length" class="library-status">{{t('bank.empty')}}</p><article v-for="item in bank.items" :key="item.id" class="library-card"><div><h3>{{item.title}}</h3><p class="library-meta">{{t(TYPE_LABELS[item.type])}}</p></div><button type="button" class="button" :disabled="busy" @click="addFromBank(item.id)">{{t('bank.addOne')}}</button></article></div></form></dialog>
 <p v-if="view==='home'&&formError" class="error" role="alert">{{formError}}</p>
 </main>
</template>
